mapper.update:
update t_stock set
is_freeze = #{isFreeze}
,origin_type = #{originType}
where del_flag = '0' and id in

    #{id}

mapper.select:


    inner join sys_user u on u.user_name = tstock.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tstock.del_flag = '0'
     and tstock.area_id = #{areaId}
     and tstock.location_id = #{locationId}
     and tstock.material_id = #{materialId}
     and tstock.batch_code like concat('%', #{batchCode}, '%')
     and tstock.unit_id = #{unitId}
     and tstock.count = #{count}
     and tstock.available_count = #{availableCount}
     and tstock.status = #{status}
     and tstock.is_freeze = #{isFreeze}
     and tstock.origin_type = #{originType}
     and tstock.tray_id = #{trayId}
     and tstock.begin_date = #{beginDate}
     and tstock.end_date = #{endDate}
     and tstock.produced_date = #{producedDate}
     and tstock.position = #{position}


${params.dataScope}

select
s.material_id
, sum(s.count) AS count
, sum(s.available_count) AS available_count
from
t_stock AS s
where s.del_flag = '0'
and s.count > 0
 and s.batch_code = #{stock.batchCode}
 and s.tray_id = #{stock.trayId}
 and s.unit_id = #{stock.unitId}
 and s.location_id = #{stock.locationId}
 and s.isFreeze = #{stock.isFreeze}
and s.material_id = #{stock.materialId}
 and s.dept_id = #{stock.deptId}

    and s.material_id in

        #{materialId}


group by s.material_id

select t1.id, t1.area_id, t1.location_id, t1.material_id, t1.batch_code, t1.unit_id, t1.`count`, t1.available_count, t1.`status`, t1.is_freeze, t1.origin_type, t1.tray_id, t1.begin_date, t1.end_date, t1.produced_date, t1.position, t1.remark, t1.create_by, t1.create_time, t1.update_by, t1.update_time, t1.dept_id, t1.dept_name, t1.del_flag from t_stock t1 left join t_tray t2 on t1.tray_id = t2.id where t1.del_flag = 0 and t1.count != 0 and t1.is_freeze = 0
and t2.tray_category = #{trayType}
and t1.material_id = #{materialId}
and t1.material_id in
#{item}
and t1.location_id in
#{item}

select s.batch_code batchCode, s.count, s.create_time createTime, m.code materialCode, m.name materialName, m.id materialId, m.specifications, l.name locationName from t_stock s left join t_material m on m.id=s.material_id left join t_location l on l.id=s.location_id left join t_tray tray on s.tray_id = tray.id where s.del_flag = '0' and m.del_flag = '0' and s.status='0' and s.is_freeze='0' and s.count != 0 and m.code like concat('%',#{materialCode},'%') and m.name like concat('%',#{materialName},'%') and s.batch_code like concat('%',#{batchCode},'%') and s.location_id=#{locationId}
and s.create_time>=#{beginDate}
and #{endDate}>=s.create_time
and tray.tray_category = #{trayType} and l.location_type != '1'
and l.location_type = '1'
order by s.id desc

select material_id
from (
         select distinct material_id from t_stock where del_flag = 0 and is_freeze = 0
     ) t
order by RAND()
limit #{value}

select * from erp_wms_batch_code where erp_num = wms_num
and type = #{type}
order by erp_code ,material_code
